('5a3e0001-0000-4000-8000-000000003905', '5a3e0000-0000-4000-8000-000000000039', 'Shop on MG Road', 9000000, 'per month', null, 'Shops', 'Ground floor, 600 sq ft, main road front.', 'shop front', 5),
('5a3e0001-0000-4000-8000-000000004001', '5a3e0000-0000-4000-8000-000000000040', 'Wedding invitation', 45000000, null, 'from', 'Personal', 'A custom illustrated invitation with your story.', 'wedding invitation', 1),
('5a3e0001-0000-4000-8000-000000004002', '5a3e0000-0000-4000-8000-000000000040', 'Café menu', 90000000, null, 'from', 'Brands', 'Illustrated menu and signage.', 'cafe menu', 2),
('5a3e0001-0000-4000-8000-000000004003', '5a3e0000-0000-4000-8000-000000000040', 'Picture book', null, null, 'Quote on request', 'Books', 'Full illustration for a children''s book.', 'picture book', 3),
('5a3e0001-0000-4000-8000-000000004004', '5a3e0000-0000-4000-8000-000000000040', 'Portrait drawing', 15000000, null, null, 'Personal', 'A hand-drawn portrait from your photo.', 'portrait drawing', 4),
('5a3e0001-0000-4000-8000-000000004101', '5a3e0000-0000-4000-8000-000000000041', 'Sponsored video', 1800000, null, 'from', 'Partnerships', 'A 60-second film for Instagram and YouTube.', 'video camera', 1),
('5a3e0001-0000-4000-8000-000000004102', '5a3e0000-0000-4000-8000-000000000041', 'Photo story', 900000, null, 'from', 'Partnerships', 'Fifteen edited photos with captions.', 'travel photography', 2),
('5a3e0001-0000-4000-8000-000000004103', '5a3e0000-0000-4000-8000-000000000041', 'Hotel feature', 2500000, null, 'from', 'Partnerships', 'A full stay review with film and photos.', 'hotel', 3),
