insert into faq (id, business_id, question, answer, sort_order) values
('5a3e0002-0000-4000-8000-000000001201', '5a3e0000-0000-4000-8000-000000000012', 'Are your candles safe for pets?', 'Yes. We use soy wax and skin-safe fragrance oils without phthalates.', 1),
('5a3e0002-0000-4000-8000-000000001202', '5a3e0000-0000-4000-8000-000000000012', 'Can I order 50 candles for a wedding?', 'Yes. Wedding orders need two weeks notice. Write to us for a price.', 2),
('5a3e0002-0000-4000-8000-000000001301', '5a3e0000-0000-4000-8000-000000000013', 'Do you give a certificate?', 'Every piece comes with a gold purity certificate and a stone certificate where relevant.', 1),
('5a3e0002-0000-4000-8000-000000001302', '5a3e0000-0000-4000-8000-000000000013', 'Can I see pieces in person?', 'Yes. Book a visit and we will have your pieces ready.', 2),
('5a3e0002-0000-4000-8000-000000001401', '5a3e0000-0000-4000-8000-000000000014', 'Do you buy books?', 'Yes, on Tuesday mornings. We pay in cash or store credit.', 1),
('5a3e0002-0000-4000-8000-000000001402', '5a3e0000-0000-4000-8000-000000000014', 'Can you find a book I need?', 'Tell us the title and we will order it within a week.', 2),
('5a3e0002-0000-4000-8000-000000001501', '5a3e0000-0000-4000-8000-000000000015', 'Do you ship abroad?', 'Yes, to the US and Canada. Write to us for a price.', 1),
('5a3e0002-0000-4000-8000-000000001502', '5a3e0000-0000-4000-8000-000000000015', 'Are your plates food safe?', 'Yes. All tableware uses lead-free glazes.', 2),
('5a3e0002-0000-4000-8000-000000001601', '5a3e0000-0000-4000-8000-000000000016', 'Do you make custom sizes?', 'Yes. Send us your measurements with your order.', 1),
('5a3e0002-0000-4000-8000-000000001602', '5a3e0000-0000-4000-8000-000000000016', 'Will the colour fade?', 'Indigo softens gently. Wash cold and inside out.', 2),
('5a3e0002-0000-4000-8000-000000001701', '5a3e0000-0000-4000-8000-000000000017', 'Is everything certified organic?', 'Yes. Every farmer group we buy from is certified, and we show the certificate on request.', 1),
('5a3e0002-0000-4000-8000-000000001702', '5a3e0000-0000-4000-8000-000000000017', 'Can I return vegetables?', 'If anything is not fresh, tell us the same day and we refund it.', 2),
('5a3e0002-0000-4000-8000-000000001801', '5a3e0000-0000-4000-8000-000000000018', 'Do you engrave pens?', 'Yes, from £8. It takes two working days.', 1),
('5a3e0002-0000-4000-8000-000000001802', '5a3e0000-0000-4000-8000-000000000018', 'Do you ship abroad?', 'Yes, to most countries. Shipping is shown at checkout.', 2),
('5a3e0002-0000-4000-8000-000000001901', '5a3e0000-0000-4000-8000-000000000019', 'Do you have food samples?', 'Yes. Ask in store for a free sample before buying a big bag.', 1),
('5a3e0002-0000-4000-8000-000000001902', '5a3e0000-0000-4000-8000-000000000019', 'Can I return opened food?', 'If your pet will not eat it, return it within 14 days for store credit.', 2),
('5a3e0002-0000-4000-8000-000000002001', '5a3e0000-0000-4000-8000-000000000020', 'Is the food very spicy?', 'Medium. Ask for mild when you order and we make it mild.', 1),
('5a3e0002-0000-4000-8000-000000002002', '5a3e0000-0000-4000-8000-000000000020', 'Do you cook with onion and garlic?', 'Yes. Tell us if you need a no-onion no-garlic meal.', 2),
('5a3e0002-0000-4000-8000-000000002101', '5a3e0000-0000-4000-8000-000000000021', 'Do you have vegan options?', 'Yes. Most dishes can be made vegan, and oat milk is free.', 1),
('5a3e0002-0000-4000-8000-000000002102', '5a3e0000-0000-4000-8000-000000000021', 'Can I book a table?', 'We do not take bookings. Walk in any time.', 2),
('5a3e0002-0000-4000-8000-000000002201', '5a3e0000-0000-4000-8000-000000000022', 'Do you have gluten-free bread?', 'Not yet. Our kitchen uses wheat flour everywhere.', 1),
('5a3e0002-0000-4000-8000-000000002202', '5a3e0000-0000-4000-8000-000000000022', 'Can I reserve bread?', 'Yes. Order before 18:00 for the next morning.', 2),
('5a3e0002-0000-4000-8000-000000002301', '5a3e0000-0000-4000-8000-000000000023', 'Can you make it less spicy?', 'Yes. Choose mild, medium or Thai hot.', 1),
('5a3e0002-0000-4000-8000-000000002302', '5a3e0000-0000-4000-8000-000000000023', 'Is there a vegetarian menu?', 'Most dishes can be made with tofu.', 2),
('5a3e0002-0000-4000-8000-000000002401', '5a3e0000-0000-4000-8000-000000000024', 'What is the minimum order?', 'Twenty plates.', 1),
('5a3e0002-0000-4000-8000-000000002402', '5a3e0000-0000-4000-8000-000000000024', 'Do you provide servers?', 'Yes, one server for every 25 guests, KSh 2,500 each.', 2),
('5a3e0002-0000-4000-8000-000000002501', '5a3e0000-0000-4000-8000-000000000025', 'Do you accept insurance?', 'We give itemised bills you can claim from your insurer.', 1),
('5a3e0002-0000-4000-8000-000000002502', '5a3e0000-0000-4000-8000-000000000025', 'Is there parking?', 'Yes, in front of the clinic.', 2),
('5a3e0002-0000-4000-8000-000000002601', '5a3e0000-0000-4000-8000-000000000026', 'Do I need a GP referral?', 'No. You can book directly.', 1),
('5a3e0002-0000-4000-8000-000000002602', '5a3e0000-0000-4000-8000-000000000026', 'Do you work with insurers?', 'Yes, with most major UK health insurers.', 2),
('5a3e0002-0000-4000-8000-000000002701', '5a3e0000-0000-4000-8000-000000000027', 'Do you give a warranty?', 'Three months or 5,000 km on all our work.', 1),
('5a3e0002-0000-4000-8000-000000002702', '5a3e0000-0000-4000-8000-000000000027', 'Can I wait while you work?', 'Yes, oil changes take about 45 minutes.', 2),
('5a3e0002-0000-4000-8000-000000002801', '5a3e0000-0000-4000-8000-000000000028', 'Which software do you use?', 'Xero or QuickBooks, whichever you prefer.', 1),
('5a3e0002-0000-4000-8000-000000002802', '5a3e0000-0000-4000-8000-000000000028', 'Can I cancel any time?', 'Yes, with one month''s notice.', 2),
('5a3e0002-0000-4000-8000-000000002901', '5a3e0000-0000-4000-8000-000000000029', 'Do I need to be home?', 'No. Many clients leave a key with the building guard.', 1),
('5a3e0002-0000-4000-8000-000000002902', '5a3e0000-0000-4000-8000-000000000029', 'Do you bring supplies?', 'Yes, including a vacuum.', 2),
('5a3e0002-0000-4000-8000-000000003001', '5a3e0000-0000-4000-8000-000000000030', 'Can you copy a design from a photo?', 'Yes. Bring or send the photo when you book.', 1),
('5a3e0002-0000-4000-8000-000000003002', '5a3e0000-0000-4000-8000-000000000030', 'Do you pick up from home?', 'Within Surat city, for ₹100.', 2),
('5a3e0002-0000-4000-8000-000000003101', '5a3e0000-0000-4000-8000-000000000031', 'Do I need my own mat?', 'No. Mats and blocks are provided.', 1),
('5a3e0002-0000-4000-8000-000000003102', '5a3e0000-0000-4000-8000-000000000031', 'Is it suitable for beginners?', 'Yes. Most of our students are beginners.', 2),
('5a3e0002-0000-4000-8000-000000003201', '5a3e0000-0000-4000-8000-000000000032', 'Do classes run online?', 'Yes, every course is offered online and in person.', 1),
('5a3e0002-0000-4000-8000-000000003202', '5a3e0000-0000-4000-8000-000000000032', 'Does my child need a laptop?', 'For online classes, yes. In person, we provide computers.', 2),
('5a3e0002-0000-4000-8000-000000003301', '5a3e0000-0000-4000-8000-000000000033', 'Do I need my own instrument?', 'Not for lessons at the school.', 1),
('5a3e0002-0000-4000-8000-000000003302', '5a3e0000-0000-4000-8000-000000000033', 'What age can children start?', 'From six years old.', 2),
('5a3e0002-0000-4000-8000-000000003401', '5a3e0000-0000-4000-8000-000000000034', 'Do you have showers?', 'Yes, with lockers.', 1),
('5a3e0002-0000-4000-8000-000000003402', '5a3e0000-0000-4000-8000-000000000034', 'Can I freeze my membership?', 'Yes, for up to one month a year.', 2),
('5a3e0002-0000-4000-8000-000000003501', '5a3e0000-0000-4000-8000-000000000035', 'Is breakfast included?', 'Yes, breakfast and dinner are included in every room price.', 1),
('5a3e0002-0000-4000-8000-000000003502', '5a3e0000-0000-4000-8000-000000000035', 'Can we bring our dog?', 'Yes, in the Estate cottage, for ₹500 a night.', 2),
('5a3e0002-0000-4000-8000-000000003601', '5a3e0000-0000-4000-8000-000000000036', 'Is breakfast included?', 'Yes, for every room.', 1),
('5a3e0002-0000-4000-8000-000000003602', '5a3e0000-0000-4000-8000-000000000036', 'How far is the airport?', 'About 75 minutes by car.', 2),
('5a3e0002-0000-4000-8000-000000003701', '5a3e0000-0000-4000-8000-000000000037', 'Do you plan weddings outside Udaipur?', 'Yes, across Rajasthan.', 1),
('5a3e0002-0000-4000-8000-000000003702', '5a3e0000-0000-4000-8000-000000000037', 'Can you help guests from abroad?', 'Yes. We arrange airport pickups, hotels and local SIM cards.', 2),
('5a3e0002-0000-4000-8000-000000003801', '5a3e0000-0000-4000-8000-000000000038', 'When do we get our photos?', 'Within three weeks, in an online gallery.', 1),
('5a3e0002-0000-4000-8000-000000003802', '5a3e0000-0000-4000-8000-000000000038', 'Do you travel?', 'Yes, anywhere in Türkiye.', 2),
('5a3e0002-0000-4000-8000-000000003901', '5a3e0000-0000-4000-8000-000000000039', 'Are the photos real?', 'Yes. We take every photo ourselves on our visit.', 1),
('5a3e0002-0000-4000-8000-000000003902', '5a3e0000-0000-4000-8000-000000000039', 'How soon can I move in?', 'Most homes are ready within two weeks of signing.', 2),
('5a3e0002-0000-4000-8000-000000004001', '5a3e0000-0000-4000-8000-000000000040', 'Do you work with clients abroad?', 'Yes. Most of my book work is for publishers outside Korea.', 1),
('5a3e0002-0000-4000-8000-000000004002', '5a3e0000-0000-4000-8000-000000000040', 'Can I print the files myself?', 'Yes. You get print-ready files.', 2),
('5a3e0002-0000-4000-8000-000000004101', '5a3e0000-0000-4000-8000-000000000041', 'Do you need a free stay?', 'For hotel features, yes. For everything else we charge the fee shown.', 1),
('5a3e0002-0000-4000-8000-000000004102', '5a3e0000-0000-4000-8000-000000000041', 'Can we see past work?', 'Yes. Ask us for our media kit and recent results.', 2);

-- Shop samples with bargaining on, like the earlier shop samples.
insert into site_extras (business_id, haggle_on, haggle_max_off, haggle_min_qty)
select id, true, 12, 1 from business where id in ('5a3e0000-0000-4000-8000-000000000012', '5a3e0000-0000-4000-8000-000000000013', '5a3e0000-0000-4000-8000-000000000015', '5a3e0000-0000-4000-8000-000000000016')
on conflict (business_id) do nothing;
